  var early=new CompoundTag();check(!Quest185State.earlyReady(early,true),"eye needs valid defeat evidence");early.putBoolean("Likho",true);check(Quest185State.earlyReady(early,true),"Likho alone unlocks before Ovinnik and Poloz");check(!Quest185State.earlyReady(early,false),"show eye without consuming");check(Quest185State.claimEarly(early,true),"first early research receipt");check(!Quest185State.claimEarly(early,true),"repeat research no duplicate");check(early.getBoolean("Cleansing")&&early.getBoolean("EarthAccepted"),"knowledge and optional parallel quest");check(!Quest185State.earthReady(early,19),"nineteen insufficient");check(Quest185State.claimEarth(early,20),"twenty receipt independent of main Q3");check(!Quest185State.claimEarth(early,20),"earth reward one time");check(!early.getBoolean("Ovinnik")&&!early.getBoolean("Poloz"),"no false boss victories");var usedEye=new CompoundTag();usedEye.putBoolean("Horn",true);check(Quest185State.earlyReady(usedEye,false),"crafted horn accepts consumed trophy proof");
  var shown=new CompoundTag();shown.putBoolean("Likho",true);shown.putBoolean("EyeShown",true);check(Quest185State.earlyReady(shown,false),"previously shown eye remains evidence after loss");
