  var nativeMethod=net.minecraft.world.inventory.CraftingMenu.class.getDeclaredMethod("slotChangedCraftingGrid",net.minecraft.world.inventory.AbstractContainerMenu.class,net.minecraft.world.level.Level.class,net.minecraft.world.entity.player.Player.class,net.minecraft.world.inventory.CraftingContainer.class,net.minecraft.world.inventory.ResultContainer.class,net.minecraft.world.item.crafting.RecipeHolder.class);check(java.lang.reflect.Modifier.isStatic(nativeMethod.getModifiers()),"installed menu API matches mixin");
  check(net.minecraft.world.level.block.CrafterBlock.class.getDeclaredMethod("getPotentialResults",net.minecraft.world.level.Level.class,net.minecraft.world.item.crafting.CraftingInput.class)!=null,"installed crafter API");
  check(net.minecraft.world.level.chunk.LevelChunk.class.getDeclaredMethod("setBlockState",BlockPos.class,net.minecraft.world.level.block.state.BlockState.class,boolean.class).getReturnType()==net.minecraft.world.level.block.state.BlockState.class,"installed block-change mixin API");
  net.neoforged.fml.loading.LoadingModList.of(List.of(),List.of(),List.of(),List.of(),Map.of());net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();
  var recipeJson=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(java.nio.file.Path.of("src/main/resources/data/slavicmyths/recipe/cleansing_powder.json")));
